var p=UnityEngine.Object.FindFirstObjectByType<CurtainCall.ItemArt.ItemGameplayPlayground>();var actor=p.Player.GetComponent<CurtainCall.Player.HumanoidPlayerPresentation>();var slot=p.Player.GetComponent<CurtainCall.Player.PlayerModelSlot>();var condition=p.Player.GetComponent<CurtainCall.Player.PlayerCondition>();var mover=p.Player.GetComponent<CurtainCall.Player.PlayerMover>();
